use std::collections::HashMap;
use std::error::Error;

#[derive(Deserialize)]
struct Interaction {
    src: i64,
    dst: i64,
    weight: i64,
}

#[derive(Serialize)]
struct OutputRecord {
    id: i64,
    name: String,
    centrality: i64,
}

fn main() -> Result<(), Box<dyn Error>> {
    let conn = Connection::open("/home/user/data.db")?;
    let mut user_names = HashMap::new();
    {
        let mut stmt = conn.prepare("SELECT id, name FROM users")?;
        let rows = stmt.query_map([], |row| {
            Ok((row.get::<_, i64>(0)?, row.get::<_, String>(1)?))
        })?;
        for row in rows {
            let (id, name) = row?;
            user_names.insert(id, name);
        }
    }

    let data = std::fs::read_to_string("/home/user/interactions.json")?;
    let interactions: Vec<Interaction> = serde_json::from_str(&data)?;

    let mut centrality: HashMap<i64, i64> = HashMap::new();
    for inter in &interactions {
        *centrality.entry(inter.src).or_insert(0) += inter.weight;
        *centrality.entry(inter.dst).or_insert(0) += inter.weight;
    }

    let mut records: Vec<OutputRecord> = Vec::new();
    for (id, score) in centrality {
        if score < 10 {
            continue;
        }
        if let Some(name) = user_names.get(&id) {
            records.push(OutputRecord {
                id,
                name: name.clone(),
                centrality: score,
            });
        }
    }

    records.sort_by(|a, b| {
        b.centrality.cmp(&a.centrality)
            .then_with(|| a.name.cmp(&b.name))
    });

    const PAGE_SIZE: usize = 3;
    const PAGE: usize = 3;
    let start = ((PAGE - 1) * PAGE_SIZE).min(records.len());
    let end = (start + PAGE_SIZE).min(records.len());
    let page: Vec<OutputRecord> = records[start..end].to_vec();

    let output = serde_json::to_string_pretty(&page)?;
    std::fs::write("/home/user/output_page3.json", output)?;

    println!("Generated /home/user/output_page3.json");
    Ok(())
}
